        const dvd = document.getElementById('dvdLogo');
        const topWall = document.getElementById('topWall');
        const bottomWall = document.getElementById('bottomWall');
        const leftWall = document.getElementById('leftWall');
        const rightWall = document.getElementById('rightWall');

        let dvdx = 10; // horizontal speed
        let dvdy = -8; // vertical speed (negative for upward movement)
        let dvdWidth = dvd.offsetWidth;
        let dvdHeight = dvd.offsetHeight;
        let wallThickness = 30;

        function update() {
            dvd.style.left = dvd.getBoundingClientRect().left + 'px';
            dvd.style.top = dvd.getBoundingClientRect().top + 'px';

            // Move the DVD
            dvd.style.transform = `translate(${dvd.offsetWidth / 2 + dvdx}px, ${dvdy}px)`;

            // Check for collisions with walls
            if (dvdy < 0 && dvd.getBoundingClientRect().top <= topWall.offsetHeight) {
                dvdy *= -1; // Bounce vertically
            } else if (dvdy > 0 && dvd.getBoundingClientRect().bottom >= window.innerHeight - bottomWall.offsetHeight) {
                dvdy *= -1; // Bounce vertically
