            } else if (dvx > 0 && dvd.getBoundingClientRect().right >= window.innerWidth - rightWall.offsetWidth) {
                dvdx *= -1; // Bounce horizontally
            }

            requestAnimationFrame(update);
        }

        update();
    </script>
